const details={"sim": ["Commission and Subsidy Strategies in E-commerce Platforms: An Agent-Based Simulation", "Built a multi-agent simulation with four types of participants. Designed single-platform static, two-platform static competition, and two-platform dynamic game experiments. Compared 16 strategy combinations and used Pareto frontiers to investigate the trade-offs between scale, returns, and ecosystem stability."], "rec": ["Learning Dynamic Reading Interests with Sequential Recommendation", "Benchmarked NCF, DeepFM, and DCN to identify limitations of static recommendation models. Used BERT4Rec for dynamic user interests, data augmentation to address sparsity, and a hybrid model to improve recommendations. Ranked 2nd out of 333 in the CCF Big Data and Computational Intelligence Competition training round."], "gai": ["Technology for All: Social Equity and Development in the Generative AI Era", "Collected data through web scraping and other channels. Applied sentiment analysis, principal component analysis, panel regression, and spatial-effect analysis to study inclusive generative AI development. Contributed to the full research report and presentation materials, coordinated with the supervisor, and led three project defenses. Received a national second prize."], "flow": ["An AI Skill for Automated Platform Coupon Analysis", "Independently designed an AI Skill to reduce repetitive monthly coupon analysis. Integrated Feishu for automated data reading, standardized extraction, month-over-month comparisons, and writing back findings. The workflow helped identify changes in coupon strategies across platforms and months."]};
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button))});document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter})}));
const dialog=document.getElementById('detail');document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const item=details[button.dataset.detail];document.getElementById('detail-title').textContent=item[0];document.getElementById('detail-body').textContent=item[1];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close()}});
const menu=document.querySelector('.menu-toggle');const links=document.querySelector('.nav-links');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');links.classList.toggle('open',open)});links.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{links.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}));document.addEventListener('keydown',event=>{if(event.key==='Escape'){links.classList.remove('open');menu.setAttribute('aria-expanded','false');document.getElementById('author-links').classList.remove('open');document.querySelector('.profile-toggle').setAttribute('aria-expanded','false')}});
const profile=document.querySelector('.profile-toggle');profile.addEventListener('click',()=>{const open=profile.getAttribute('aria-expanded')!=='true';profile.setAttribute('aria-expanded',String(open));document.getElementById('author-links').classList.toggle('open',open)});
